-- Centro geometrico de cada pais, en ISO alpha-2. Es el punto de reserva del mapa en vivo:
-- cuando Netlify nos da el pais pero no la ciudad, el visitante se pinta aqui.
-- Generado por tools/crm-qa/gen_mundo.py desde Natural Earth 110m (dominio publico).
create table if not exists public.geo_paises (
  code text primary key,
  lon  double precision not null,
  lat  double precision not null
);
alter table public.geo_paises enable row level security;   -- sin politicas: solo la clave de servidor
